const cfg = $('Config').first().json;
const num = (v) => { const n = Number(v); return isFinite(n) ? n : 0; };
const uniq = (rows, key) => { const seen = {}; const out = []; rows.forEach(r => { const k = String(r[key] || '').trim(); if (k && !seen[k]) { seen[k] = true; out.push(r); } }); return out; };
const pol = uniq($('Read Policy').all().map(i => i.json).filter(r => r && r.policy_key), 'policy_key');
const reps = uniq($('Read Reps').all().map(i => i.json).filter(r => r && r.rep_id), 'rep_id');
const outs = uniq($('Read Outlets').all().map(i => i.json).filter(r => r && r.outlet_id), 'outlet_id');
const prods = uniq($('Read Products').all().map(i => i.json).filter(r => r && r.sku), 'sku');
const logs = uniq($('Read Visit Logs').all().map(i => i.json).filter(r => r && r.log_id), 'log_id');
const recs = uniq($('Read Visit Records').all().map(i => i.json).filter(r => r && r.record_id), 'record_id');
const pipe = uniq($('Read Pipeline').all().map(i => i.json).filter(r => r && r.opp_id), 'opp_id');
const P = {};
pol.forEach(r => { P[String(r.policy_key).trim()] = r.policy_value; });
const repBy = {}; reps.forEach(r => { repBy[String(r.rep_id).trim()] = r; });
const outBy = {}; outs.forEach(r => { outBy[String(r.outlet_id).trim()] = r; });
const pipeBy = {}; pipe.forEach(r => { pipeBy[String(r.outlet_id).trim()] = r; });
const dedupe = (String(cfg.dedupe_enabled) === 'true') || (cfg.dedupe_enabled === true);
const done = {}; recs.forEach(r => { done[String(r.log_id || '').trim()] = true; });
const pad = (n) => String(n).padStart(2, '0');
const now = new Date(Date.now() + (num(cfg.tz_offset_minutes) || 330) * 60000);
const fd = (d) => d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
const today = fd(now);
const stamp = now.getUTCFullYear() + pad(now.getUTCMonth() + 1) + pad(now.getUTCDate()) + pad(now.getUTCHours()) + pad(now.getUTCMinutes());
const issues = [];
let skipped = 0;
const open = [];
logs.forEach(l => {
  const lid = String(l.log_id).trim();
  if (String(l.status || '').toLowerCase().trim() === 'processed') { skipped += 1; return; }
  if (dedupe && done[lid]) { skipped += 1; return; }
  const o = outBy[String(l.outlet_id || '').trim()];
  const r = repBy[String(l.rep_id || '').trim()];
  if (!o || !r) { issues.push('Missing outlet or rep for visit ' + lid); return; }
  const pp = pipeBy[String(l.outlet_id).trim()] || null;
  const audio = String(l.audio_b64 || '').trim();
  open.push({ log_id: lid, channel: String(l.channel || 'text'), raw_text: String(l.raw_text || ''), audio_b64: audio, has_audio: audio.length > 100,
    rep_id: String(r.rep_id), rep_name: String(r.name || ''), rep_email: String(r.email || ''),
    outlet_id: String(o.outlet_id), outlet_name: String(o.name || ''), outlet_type: String(o.type || ''), owner_name: String(o.owner_name || ''),
    area: String(o.area || ''), tier: String(o.tier || 'C').toUpperCase().trim(),
    potential: num(o.monthly_potential_inr), current: num(o.current_monthly_inr), outlet_status: String(o.status || 'active'),
    stage_now: pp ? String(pp.stage || '') : '', opp_id: pp ? String(pp.opp_id || '') : '', opp_value: pp ? num(pp.value_inr) : 0 });
});
const batch = open.slice(0, num(cfg.max_per_run) || 12);
let cat = '';
prods.forEach(p => { cat += String(p.sku) + ' = ' + String(p.name) + ' (' + String(p.category) + ')\n'; });
let blob = '';
const audioParts = [];
batch.forEach(b => {
  blob += '=== VISIT ' + b.log_id + ' ===\nOUTLET: ' + b.outlet_name + ' (' + b.outlet_type + ', tier ' + b.tier + ', ' + b.area + '), owner ' + b.owner_name + '\nCURRENT BUSINESS: Rs ' + b.current + ' per month against a potential of Rs ' + b.potential + '\nCURRENT PIPELINE STAGE: ' + (b.stage_now || 'none') + '\n';
  if (b.has_audio) { blob += 'REP SENT A VOICE NOTE. Its audio is attached after this text, in the order the voice note visits appear. Transcribe it and parse what the rep said.\n\n'; audioParts.push({ inlineData: { mimeType: 'audio/ogg', data: b.audio_b64 } }); }
  else { blob += 'REP SAID (' + b.channel + ' note): ' + b.raw_text + '\n\n'; }
});
const prompt = 'You structure field sales visit notes for an Indian FMCG distribution company selling namkeen and chips. Reps send voice notes and texts in Hinglish, casually, often while walking between shops. Some visits below are typed, some are voice notes whose audio is attached after this text. Pull out what actually happened. Extract only what is stated. Never invent an order, a number or a commitment.\n\nPRODUCT CATALOGUE:\n' + (cat || 'none') + '\n' + (blob || 'none') + '\nIf there are no visits above, return an empty visits array.\nReturn ONLY valid JSON, no markdown fences. One key visits holding an array, one entry per VISIT block above, in the same order. Each entry has keys: log_id, visit_type, outcome, order_value_inr, discount_pct, sentiment, competitor, objection, commitment, skus_mentioned, next_step_suggestion, summary, transcript.\nlog_id must be copied exactly from the VISIT header line.\nvisit_type is exactly one of: order_taken, follow_up, sampling, first_visit, no_contact, complaint. Use no_contact when the decision maker was not available.\noutcome is exactly one of: order_placed, verbal_commitment, sampling_done, information_shared, no_progress, churn_risk. Use churn_risk when the outlet says they will stop ordering or wants to return stock.\norder_value_inr is the rupee value of an order actually placed on this visit, a plain number, 0 if none. Never estimate a future order. Hindi number words matter: athais hazaar is 28000, chalis is forty, pachas is fifty, pandrah hazaar is 15000.\ndiscount_pct is any discount the rep gave, a plain number, 0 if none.\nsentiment is positive, neutral or negative.\ncompetitor is the competitor brand named, or the word none.\nobjection is the main blocker in one short English line, or none.\ncommitment is anything the owner promised, one short English line, or none.\nskus_mentioned is an array of SKU codes from the catalogue for any product the rep named. Empty array if none.\nnext_step_suggestion is one short English line.\nsummary is one line a manager can read at a glance, in English.\ntranscript is what you heard if this was a voice note, otherwise an empty string.\nNo em-dashes anywhere.';
const parts = [{ text: prompt }].concat(audioParts);
return [{ json: { policy: P, visits: batch, open_count: batch.length, skipped: skipped, gemini_parts: parts, audio_count: audioParts.length, products: prods, today: today, stamp: stamp, data_issues: issues, company_name: cfg.company_name, manager_email: cfg.manager_email, distributor_email: cfg.distributor_email, distributor_name: cfg.distributor_name } }];

const textOf = (resp) => { const c = resp && resp.candidates && resp.candidates[0]; const parts = (c && c.content && c.content.parts) || []; return parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(''); };
const parseJson = (raw) => { let t = String(raw || '').trim(); const s = t.indexOf('{'); const e = t.lastIndexOf('}'); if (s !== -1 && e !== -1) t = t.slice(s, e + 1); t = t.replace(/,(\s*[}\]])/g, '$1'); try { return JSON.parse(t); } catch (err) { return null; } };
const A = $('Assemble Visit Context').first().json;
const num = (v) => { const n = Number(v); return isFinite(n) ? n : 0; };
const P = A.policy || {};
const parsed = parseJson(textOf($input.first().json)) || {};
const pv = Array.isArray(parsed.visits) ? parsed.visits : [];
const pending = (A.visits || []).length;
const aiOk = pv.length > 0;
const issues = Array.isArray(A.data_issues) ? A.data_issues.slice(0) : [];
if (!aiOk && pending > 0) { issues.push('Visit parser returned nothing for ' + pending + ' visit note(s), they were logged raw without structure'); }
const by = {}; pv.forEach(v => { by[String(v.log_id || '').trim()] = v; });
const maxD = num(P.max_discount_pct) || 12;
const minO = num(P.min_order_value_inr) || 0;
const watch = String(P.competitor_watch || '').toLowerCase().split(',').map(x => x.trim()).filter(x => x);
let transcribed = 0;
const out = [];
(Array.isArray(A.visits) ? A.visits : []).forEach(v => {
  const p = by[v.log_id] || {};
  const ov = num(p.order_value_inr);
  const dc = num(p.discount_pct);
  const comp = String(p.competitor || 'none').trim();
  const tr = String(p.transcript || '').trim();
  if (v.has_audio && tr.length > 5) { transcribed += 1; }
  const flags = [];
  let appr = false;
  if (dc > maxD) { appr = true; flags.push('Discount of ' + dc + ' percent is above the ' + maxD + ' percent limit, needs manager approval'); }
  if (ov > 0 && minO > 0 && ov < minO) { flags.push('Order of Rs ' + ov + ' is below the Rs ' + minO + ' minimum that justifies a visit'); }
  if (comp.toLowerCase() !== 'none' && comp.length > 1 && watch.indexOf(comp.toLowerCase()) === -1) { flags.push('New competitor not on the watch list: ' + comp); }
  if (String(p.outcome || '').trim() === 'churn_risk') { flags.push('Outlet is signalling they will stop ordering'); }
  out.push(Object.assign({}, v, { visit_type: String(p.visit_type || 'follow_up'), outcome: String(p.outcome || 'no_progress'), order_value: ov, discount_pct: dc, sentiment: String(p.sentiment || 'neutral'), competitor: comp, objection: String(p.objection || 'none'), commitment: String(p.commitment || 'none'), skus_mentioned: Array.isArray(p.skus_mentioned) ? p.skus_mentioned : [], transcript: tr, next_step_suggestion: String(p.next_step_suggestion || ''), ai_summary: String(p.summary || ''), needs_approval: appr, validation_flags: flags, parsed_ok: !!p.visit_type }));
});
return [{ json: { validated: out, ai_ok: aiOk, transcribed: transcribed, data_issues: issues } }];

const A = $('Assemble Visit Context').first().json;
const V = $input.first().json;
const num = (v) => { const n = Number(v); return isFinite(n) ? n : 0; };
const uniq = (rows, key) => { const seen = {}; const out = []; rows.forEach(r => { const k = String(r[key] || '').trim(); if (k && !seen[k]) { seen[k] = true; out.push(r); } }); return out; };
const orders = uniq($('Read Orders').all().map(i => i.json).filter(r => r && r.order_id), 'order_id');
const prods = Array.isArray(A.products) ? A.products : [];
const allSkus = prods.map(p => String(p.sku).trim());
const pBy = {}; prods.forEach(p => { pBy[String(p.sku).trim()] = p; });
const hist = {};
orders.forEach(o => { const oid = String(o.outlet_id || '').trim(); if (!oid) { return; } if (!hist[oid]) { hist[oid] = {}; } String(o.sku_codes || '').split(',').map(x => x.trim()).filter(x => x).forEach(s => { hist[oid][s] = true; }); });
const out = [];
(Array.isArray(V.validated) ? V.validated : []).forEach(v => {
  const h = hist[v.outlet_id] || {};
  const stocked = Object.keys(h);
  const todaySkus = (v.skus_mentioned || []).map(x => String(x).trim()).filter(x => allSkus.indexOf(x) !== -1);
  const known = {};
  stocked.forEach(s => { known[s] = true; });
  todaySkus.forEach(s => { known[s] = true; });
  const never = allSkus.filter(s => !known[s]);
  const neverNames = never.map(s => (pBy[s] || {}).name || s);
  let tName = ''; let tM = -1;
  never.forEach(s => { const m = num((pBy[s] || {}).margin_pct); if (m > tM) { tM = m; tName = (pBy[s] || {}).name || s; } });
  const rec = never.length > 0 ? ('Never stocked ' + tName + ', which carries a ' + tM + ' percent margin. Pitch it next visit.') : 'Stocks the full range already.';
  out.push(Object.assign({}, v, { sku_history: stocked, sku_today: todaySkus, sku_never: never, sku_never_names: neverNames, sku_gap_count: never.length, top_pitch_name: tName, sku_recommendation: rec, range_pct: allSkus.length > 0 ? Math.round((Object.keys(known).length / allSkus.length) * 100) : 0 }));
});
return [{ json: { enriched: out, total_skus: allSkus.length, ai_ok: V.ai_ok, transcribed: V.transcribed, data_issues: V.data_issues } }];

const A = $('Assemble Visit Context').first().json;
const V = $input.first().json;
const num = (v) => { const n = Number(v); return isFinite(n) ? n : 0; };
const P = A.policy || {};
const hot = num(P.hot_score) || 75;
const warm = num(P.warm_score) || 50;
const out = [];
(Array.isArray(V.enriched) ? V.enriched : []).forEach(v => {
  let s = 0;
  const why = [];
  if (v.tier === 'A') { s += 18; why.push('tier A outlet'); } else if (v.tier === 'B') { s += 12; why.push('tier B outlet'); } else { s += 5; why.push('tier C outlet'); }
  const hr = v.potential > 0 ? (v.potential - v.current) / v.potential : 0;
  s += Math.round(hr * 22);
  if (hr >= 0.6) { why.push('only doing ' + Math.round((v.current / (v.potential || 1)) * 100) + ' percent of what this outlet could do'); }
  if (v.order_value > 0) { const sh = v.potential > 0 ? v.order_value / v.potential : 0; s += Math.min(28, Math.round(sh * 60) + 10); why.push('ordered Rs ' + v.order_value + ' on this visit'); }
  if (v.outcome === 'verbal_commitment') { s += 16; why.push('owner made a verbal commitment'); }
  if (v.outcome === 'sampling_done') { s += 14; why.push('sampling completed, trial likely'); }
  if (v.outcome === 'information_shared') { s += 8; why.push('price list and samples shared'); }
  if (v.outcome === 'churn_risk') { s -= 35; why.push('outlet is threatening to stop ordering'); }
  if (v.outcome === 'no_progress') { s -= 5; }
  if (v.sentiment === 'positive') { s += 10; why.push('owner was positive'); } else if (v.sentiment === 'negative') { s -= 18; why.push('owner was unhappy'); }
  if (v.sku_gap_count >= 3) { s += 8; why.push(v.sku_gap_count + ' of ' + V.total_skus + ' products never stocked here, real room to widen the range'); }
  if (String(v.competitor || 'none').toLowerCase() !== 'none') { s -= 8; why.push(String(v.competitor) + ' is actively working this outlet'); }
  if (String(v.objection || 'none').toLowerCase() !== 'none') { s -= 6; }
  if (v.outlet_status === 'prospect' && v.potential >= 150000) { s += 14; why.push('new prospect with Rs ' + v.potential + ' monthly potential'); }
  if (v.visit_type === 'no_contact') { s = Math.round(s * 0.6); why.push('decision maker not met, score held back'); }
  s = Math.max(0, Math.min(100, Math.round(s)));
  out.push(Object.assign({}, v, { lead_score: s, lead_band: s >= hot ? 'HOT' : (s >= warm ? 'WARM' : 'COLD'), score_reasons_text: why.join('; ') }));
});
out.sort((a, b) => b.lead_score - a.lead_score);
return [{ json: { scored: out, total_skus: V.total_skus, ai_ok: V.ai_ok, transcribed: V.transcribed, data_issues: V.data_issues } }];

const S = $input.first().json;
const num = (v) => { const n = Number(v); return isFinite(n) ? n : 0; };
const pad = (n) => String(n).padStart(2, '0');
const now = new Date(Date.now() + 330 * 60000);
const fd = (d) => d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
const rank = { '': 0, none: 0, prospecting: 1, sampling: 2, negotiating: 3, ordering: 4, active: 5, at_risk: -1 };
const out = [];
let orders = 0, ov = 0, appr = 0, churn = 0, nc = 0, adv = 0;
const comp = {};
(Array.isArray(S.scored) ? S.scored : []).forEach(v => {
  const cur = String(v.stage_now || '').toLowerCase().trim();
  let nx = cur;
  const why = [];
  if (v.outcome === 'churn_risk') { nx = 'at_risk'; why.push('Outlet signalled they will stop, moved to at risk'); }
  else if (v.order_value > 0) { nx = (cur === 'ordering' || cur === 'active') ? 'active' : 'ordering'; why.push('Order placed, moved to ' + nx); }
  else if (v.outcome === 'verbal_commitment') { nx = 'negotiating'; why.push('Verbal commitment taken, moved to negotiating'); }
  else if (v.outcome === 'sampling_done') { nx = 'sampling'; why.push('Sampling completed, moved to sampling'); }
  else if (v.outcome === 'information_shared' && (!cur || cur === 'none')) { nx = 'prospecting'; why.push('First contact made, opened at prospecting'); }
  else if (v.visit_type === 'no_contact') { why.push('Decision maker not met, stage held at ' + (cur || 'none')); }
  else { why.push('No qualifying event, stage unchanged'); }
  const moved = nx !== cur;
  if (moved && (rank[nx] || 0) > (rank[cur] || 0)) { adv += 1; }
  if (v.order_value > 0) { orders += 1; ov += v.order_value; }
  if (v.needs_approval) { appr += 1; }
  if (v.outcome === 'churn_risk') { churn += 1; }
  if (v.visit_type === 'no_contact') { nc += 1; }
  const c = String(v.competitor || 'none').trim();
  if (c.toLowerCase() !== 'none' && c.length > 1) { comp[c] = (comp[c] || 0) + 1; }
  out.push(Object.assign({}, v, { stage_before: cur || 'none', stage_after: nx || 'none', stage_moved: moved, stage_reasons_text: why.join('; '), opp_value_new: v.order_value > 0 ? Math.max(num(v.opp_value), v.potential) : (num(v.opp_value) || v.potential), next_step_date: fd(new Date(now.getTime() + (v.tier === 'A' ? 3 : (v.tier === 'B' ? 7 : 14)) * 86400000)) }));
});
const cl = Object.keys(comp).map(k => ({ name: k, mentions: comp[k] }));
cl.sort((a, b) => b.mentions - a.mentions);
let lines = '';
out.forEach((v, i) => { lines += (i + 1) + '. ' + v.log_id + ' | ' + v.rep_name + ' | ' + v.outlet_name + ' (tier ' + v.tier + ') | ' + v.visit_type + ' | outcome: ' + v.outcome + (v.order_value > 0 ? (' | order Rs ' + v.order_value) : '') + ' | score ' + v.lead_score + ' ' + v.lead_band + ' | stage ' + v.stage_before + ' to ' + v.stage_after + ' | mood: ' + v.sentiment + (String(v.objection).toLowerCase() !== 'none' ? (' | blocker: ' + v.objection) : '') + (String(v.competitor).toLowerCase() !== 'none' ? (' | competitor: ' + v.competitor) : '') + ' | never stocked: ' + (v.sku_never_names.join(', ') || 'nothing') + '\n'; });
return [{ json: { processed: out, processed_count: out.length, orders: orders, order_value: ov, approvals_needed: appr, churn_risks: churn, no_contact: nc, stages_advanced: adv, competitors: cl, visit_lines: lines || 'none', total_skus: S.total_skus, ai_ok: S.ai_ok, transcribed: S.transcribed, data_issues: S.data_issues } }];

const textOf = (resp) => { const c = resp && resp.candidates && resp.candidates[0]; const parts = (c && c.content && c.content.parts) || []; return parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(''); };
const parseJson = (raw) => { let t = String(raw || '').trim(); const s = t.indexOf('{'); const e = t.lastIndexOf('}'); if (s !== -1 && e !== -1) t = t.slice(s, e + 1); t = t.replace(/,(\s*[}\]])/g, '$1'); try { return JSON.parse(t); } catch (err) { return null; } };
const A = $('Assemble Visit Context').first().json;
const E = $('Pipeline Engine').first().json;
const parsed = parseJson(textOf($input.first().json)) || {};
const fu = Array.isArray(parsed.followups) ? parsed.followups : [];
const by = {}; fu.forEach(f => { by[String(f.log_id || '').trim()] = f; });
const pad = (n) => String(n).padStart(2, '0');
const out = [];
(Array.isArray(E.processed) ? E.processed : []).forEach((v, i) => {
  const f = by[v.log_id] || {};
  const act = String(f.rep_action || v.next_step_suggestion || 'Follow up on the next beat cycle');
  const flags = (v.validation_flags || []).join('; ') || 'none';
  out.push({ json: Object.assign({}, v, { record_id: 'VR' + A.stamp + '-' + pad(i + 1), order_id: 'OD' + A.stamp + '-' + pad(i + 1), visit_date: A.today, rep_action: act, next_step: act, owner_message: String(f.owner_message || ''), coaching_note: String(f.coaching_note || ''), flags_text: flags, flags: flags, order_value_inr: v.order_value, distributor_email: A.distributor_email, distributor_name: A.distributor_name, company_name: A.company_name }) });
});
return out;

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $input.all().map(i => i.json).filter(r => r && Number(r.order_value) > 0);
if (rows.length === 0) { return []; }
const A = $('Assemble Visit Context').first().json;
const pBy = {};
(Array.isArray(A.products) ? A.products : []).forEach(p => { pBy[String(p.sku).trim()] = p; });
const SL = '#132A3A', AM = '#D98324', CR = '#FBF8F1', WH = '#FFFFFF', IN = '#1A1A1A', GY = '#6A6A6A', GN = '#1B7E42';
const out = [];
rows.forEach(r => {
  const skus = Array.isArray(r.sku_today) ? r.sku_today : [];
  let sh = '';
  skus.forEach(s => { const p = pBy[s] || {}; sh += '<tr><td style="padding:9px 12px;border-bottom:1px solid #E8E2D6;font-size:13px;color:' + IN + ';">' + esc(p.name || s) + '</td><td align="right" style="padding:9px 12px;border-bottom:1px solid #E8E2D6;font-size:12.5px;color:' + GY + ';">' + esc(s) + '</td></tr>'; });
  if (!sh) { sh = '<tr><td colspan="2" style="padding:9px 12px;font-size:12.5px;color:' + GY + ';">Rep did not name specific products. Confirm the mix before dispatch.</td></tr>'; }
  const dc = Number(r.discount_pct) || 0;
  const hold = !!r.needs_approval;
  const ap = hold ? ('<tr><td style="padding:2px 26px 14px 26px;"><div style="background:#FFF4E0;border-left:4px solid ' + AM + ';border-radius:6px;padding:12px 14px;font-size:13px;color:#7A4A10;"><strong>Hold for approval.</strong> ' + esc(r.flags_text) + ' Do not dispatch until the manager signs off.</div></td></tr>') : '';
  const gap = (r.sku_gap_count > 0) ? ('<tr><td style="padding:4px 26px 16px 26px;"><div style="background:' + CR + ';border-radius:7px;padding:11px 13px;font-size:12.5px;color:' + IN + ';"><strong>Range gap.</strong> This outlet has never stocked ' + esc(r.sku_never_names.join(', ')) + '. ' + esc(r.sku_recommendation) + '</div></td></tr>') : '';
